declare(strict_types=1);

namespace Schoolbox\APIConfig;

use Alaress\Authorizer\Authorizer;
use Alaress\Web\Controller\Base;
use Aura\Router\Generator;
use Crell\ApiProblem\ApiProblem;
use Schoolbox\Application\Exception\Exception as SchoolboxException;
use Schoolbox\Config\Config;
use Schoolbox\Config\ConfigMapper;
use Schoolbox\Mapper\Exception;

class Controller extends Base
{
    protected ConfigMapper $configMapper;

    /**
     * Controller constructor.
     *
     * @param Authorizer $authorizer
     * @param Generator $routeGenerator
     * @param ConfigMapper $configMapper
     */
    public function __construct(
        Authorizer $authorizer,
        Generator $routeGenerator,
        ConfigMapper $configMapper
    ) {

        $this->configMapper = $configMapper;
    }

    /**
     * Returns config object by name
     *
     * @param Config $config
     * @api GET /api/config/{configName}
     */
    public function apiConfigGet(Config $config): void
    {
        $output = [
            'name' => $config->getName(),
            'value' => $config->getValue(),
            'title' => $config->getTitle(),
            'description' => $config->getDescription()
        ];

        $this->response = $this->responseAsJson($output);
    }

    /**
     * Updates a single config value
     *
     * @param Config $config
     * @api POST /api/config/{configName}
     */
    public function apiConfigPost(Config $config): void
    {
        $data = $this->request->getParsedBody();
        if (null === $data) {
            $problem = (new ApiProblem('Request BODY has an issue, it may be empty or malformed', 'Missing Argument'))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        }

        if (!isset($data['value'])) {
            $problem = (new ApiProblem("POST request must include 'value' field", 'Missing Argument'))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        }

        $config->setValue($data['value']);

        try {
            $this->configMapper->save($config);
        } catch (Exception $e) {
            $problem = (new ApiProblem($e->getMessage()))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        }

        $output = [
            'name' => $config->getName(),
            'value' => $config->getValue(),
            'title' => $config->getTitle(),
            'description' => $config->getDescription(),
        ];

        $this->response = $this->responseAsJson($output);
    }

    /**
     * Updates multiple config values in bulk
     *
     * @api POST /api/config/bulk
     */
    public function apiConfigBulkPost(): void
    {

        $data = $this->request->getParsedBody();
        if (null === $data) {
            $problem = (new ApiProblem('Request BODY has an issue, it may be empty or malformed'))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        }

        if (!isset($data['configs']) || !is_array($data['configs'])) {
            $problem = (new ApiProblem("POST request must include 'configs' array", 'Missing Argument'))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        }

        $results = [];
        $errors = [];

        foreach ($data['configs'] as $configData) {
            if (!isset($configData['name']) || !isset($configData['value'])) {
                $errors[] = "Each config must have 'name' and 'value' fields";
                continue;
            }

            try {
                $config = $this->configMapper->findOneByColumn('name', $configData['name']);
                $config->setValue($configData['value']);
                $this->configMapper->save($config);

                $results[] = [
                    'name' => $config->getName(),
                    'value' => $config->getValue(),
                    'title' => $config->getTitle(),
                    'description' => $config->getDescription(),
                    'status' => 'success'
                ];
            } catch (\Schoolbox\Mapper\Exception $e) {
                $errors[] = "Config '{$configData['name']}' not found";
            } catch (Exception $e) {
                $errors[] = "Failed to update config '{$configData['name']}': " . $e->getMessage();
            }
        }

        $output = [
            'results' => $results,
            'errors' => $errors,
            'total_processed' => count($data['configs']),
            'successful' => count($results),
            'failed' => count($errors)
        ];

        $this->response = $this->responseAsJson($output);
    }
}
